#![cfg(feature = "sieve-parse")]

//! Tests verifying that `jmap-mock` validates Sieve scripts like a real server
//! (Stalwart) with line and column diagnostics, and accepts all scripts
//! generated by `jmap-ui`.

use jmap_mock::MockServer;
use serde_json::{Value, json};

const ACCOUNT_ID: &str = "A1";
const CAP_CORE: &str = "urn:ietf:params:jmap:core";
const CAP_SIEVE: &str = "urn:ietf:params:jmap:sieve";

fn upload_blob(server: &MockServer, data: &[u8]) -> String {
    let address = server
        .origin()
        .strip_prefix("http://")
        .expect("mock serves HTTP")
        .to_owned();
    let mut stream = std::net::TcpStream::connect(&address).expect("connect to mock");
    let head = format!(
        "POST /upload/{ACCOUNT_ID} HTTP/1.1\r\n\
         Host: {address}\r\n\
         Content-Type: application/sieve\r\n\
         Content-Length: {}\r\n\
         Connection: close\r\n\r\n",
        data.len()
    );
    use std::io::{Read, Write};
    stream.write_all(head.as_bytes()).expect("write head");
    stream.write_all(data).expect("write body");
    stream.flush().expect("flush");

    let mut response = Vec::new();
    stream.read_to_end(&mut response).expect("read response");
    let header_end = response
        .windows(4)
        .position(|chunk| chunk == b"\r\n\r\n")
        .expect("response with header block");
    let (_, body) = response.split_at(header_end + 4);
    let json: Value = serde_json::from_slice(body).expect("upload response json");
    json["blobId"].as_str().expect("blobId string").to_owned()
}

fn api(server: &MockServer, body: Value) -> Value {
    let address = server
        .origin()
        .strip_prefix("http://")
        .expect("mock serves HTTP")
        .to_owned();
    let mut stream = std::net::TcpStream::connect(&address).expect("connect to mock");
    let payload = serde_json::to_vec(&body).expect("serialize body");
    let head = format!(
        "POST /jmap HTTP/1.1\r\n\
         Host: {address}\r\n\
         Content-Type: application/json\r\n\
         Content-Length: {}\r\n\
         Connection: close\r\n\r\n",
        payload.len()
    );
    use std::io::{Read, Write};
    stream.write_all(head.as_bytes()).expect("write head");
    stream.write_all(&payload).expect("write payload");
    stream.flush().expect("flush");

    let mut response = Vec::new();
    stream.read_to_end(&mut response).expect("read response");
    let header_end = response
        .windows(4)
        .position(|chunk| chunk == b"\r\n\r\n")
        .expect("response with header block");
    let (_, body) = response.split_at(header_end + 4);
    serde_json::from_slice(body).expect("api response json")
}

fn validate_blob(server: &MockServer, blob_id: &str) -> Value {
    api(
        server,
        json!({
            "using": [CAP_CORE, CAP_SIEVE],
            "methodCalls": [[
                "SieveScript/validate",
                {
                    "accountId": ACCOUNT_ID,
                    "blobId": blob_id,
                },
                "v1"
            ]],
        }),
    )
}

fn set_create(server: &MockServer, name: &str, blob_id: &str) -> Value {
    api(
        server,
        json!({
            "using": [CAP_CORE, CAP_SIEVE],
            "methodCalls": [[
                "SieveScript/set",
                {
                    "accountId": ACCOUNT_ID,
                    "create": {
                        "c1": {
                            "name": name,
                            "blobId": blob_id,
                        }
                    }
                },
                "s1"
            ]],
        }),
    )
}

fn set_update(server: &MockServer, id: &str, blob_id: &str) -> Value {
    api(
        server,
        json!({
            "using": [CAP_CORE, CAP_SIEVE],
            "methodCalls": [[
                "SieveScript/set",
                {
                    "accountId": ACCOUNT_ID,
                    "update": {
                        id: {
                            "blobId": blob_id,
                        }
                    }
                },
                "u1"
            ]],
        }),
    )
}

#[test]
fn sieve_validate_refuses_syntax_error_with_line_and_column() {
    let server = MockServer::builder().start();

    // Unknown command inside a block: reports line and column matching Stalwart.
    let blob = upload_blob(&server, b"if true {\r\n    bogus_cmd;\r\n}\r\n");
    let res = validate_blob(&server, &blob);
    let err = &res["methodResponses"][0][1]["error"];
    assert_eq!(err["type"], "invalidSieve");
    let desc = err["description"].as_str().expect("description");
    assert!(
        desc.contains("at line 1, column 7."),
        "expected line 1 and column 7 in description, got: {desc}"
    );

    // Missing semicolon / unexpected EOF.
    let blob_eof = upload_blob(&server, b"require [\"fileinto\"];\r\nkeep\r\n");
    let res_eof = validate_blob(&server, &blob_eof);
    let err_eof = &res_eof["methodResponses"][0][1]["error"];
    assert_eq!(err_eof["type"], "invalidSieve");
    let desc_eof = err_eof["description"].as_str().expect("description");
    assert!(
        desc_eof.contains("at line 3, column 0."),
        "expected line 3 and column 0 in description, got: {desc_eof}"
    );

    // Unterminated string literal.
    let blob_str = upload_blob(&server, b"require [\"fileinto\"];\r\nkeep \"unclosed;\r\n");
    let res_str = validate_blob(&server, &blob_str);
    let err_str = &res_str["methodResponses"][0][1]["error"];
    assert_eq!(err_str["type"], "invalidSieve");
    let desc_str = err_str["description"].as_str().expect("description");
    assert!(
        desc_str.contains("at line 2, column 6."),
        "expected line 2 and column 6 in description, got: {desc_str}"
    );

    // Undeclared capability.
    let blob_cap = upload_blob(&server, b"keep;\r\nfileinto \"Inbox\";\r\n");
    let res_cap = validate_blob(&server, &blob_cap);
    let err_cap = &res_cap["methodResponses"][0][1]["error"];
    assert_eq!(err_cap["type"], "invalidSieve");
    let desc_cap = err_cap["description"].as_str().expect("description");
    assert!(
        desc_cap.contains("at line 2, column 1."),
        "expected line 2 and column 1 in description, got: {desc_cap}"
    );
}

#[test]
fn sieve_set_create_and_update_refuse_unparseable_script_with_line_and_column() {
    let server = MockServer::builder().start();

    // Create with bad script.
    let bad_blob = upload_blob(&server, b"if true {\r\n    bad_cmd;\r\n}\r\n");
    let create_res = set_create(&server, "test_bad", &bad_blob);
    let not_created = &create_res["methodResponses"][0][1]["notCreated"]["c1"];
    assert_eq!(not_created["type"], "invalidSieve");
    let desc = not_created["description"].as_str().expect("description");
    assert!(
        desc.contains("at line 1, column 7."),
        "expected line 1 and column 7 in description, got: {desc}"
    );

    // Create with good script first.
    let good_blob = upload_blob(&server, b"keep;\r\n");
    let ok_res = set_create(&server, "test_good", &good_blob);
    let script_id = ok_res["methodResponses"][0][1]["created"]["c1"]["id"]
        .as_str()
        .expect("script id");

    // Update with bad script.
    let update_res = set_update(&server, script_id, &bad_blob);
    let not_updated = &update_res["methodResponses"][0][1]["notUpdated"][script_id];
    assert_eq!(not_updated["type"], "invalidSieve");
    let update_desc = not_updated["description"].as_str().expect("description");
    assert!(
        update_desc.contains("at line 1, column 7."),
        "expected line 1 and column 7 in update description, got: {update_desc}"
    );
}

#[test]
fn sieve_accepts_all_jmap_ui_generator_script_forms() {
    let server = MockServer::builder().start();

    // 1. Empty / comment-only script
    let empty_script = "# Generated by Evolution (JMAP). Edit it in Evolution's account editor.\n# evolution-jmap-rules 1\n";
    let blob_empty = upload_blob(&server, empty_script.as_bytes());
    let res_empty = validate_blob(&server, &blob_empty);
    assert!(
        res_empty["methodResponses"][0][1]["error"].is_null(),
        "empty script must be valid: {:?}",
        res_empty
    );

    // 2. Invoices rule with MoveTo (:mailboxid)
    let invoices_script = r#"# Generated by Evolution (JMAP). Edit it in Evolution's account editor.
# evolution-jmap-rules 1
require ["copy", "fileinto", "imap4flags", "mailboxid"];

# rule {"name":"Invoices","enabled":true,"conditions":[{"field":"Subject","op":"Contains","value":"invoice"}],"combine":"All","actions":[{"MoveTo":{"id":"M1","name":"Invoices"}}],"stop":true}
if header :contains "subject" "invoice" {
    fileinto :mailboxid "M1" "Invoices";
    stop;
}
"#;
    let blob_invoices = upload_blob(&server, invoices_script.as_bytes());
    let res_invoices = validate_blob(&server, &blob_invoices);
    assert!(
        res_invoices["methodResponses"][0][1]["error"].is_null(),
        "invoices script must be valid: {:?}",
        res_invoices
    );

    // 3. Mark rule with MarkRead and Flag
    let mark_script = r#"# Generated by Evolution (JMAP). Edit it in Evolution's account editor.
# evolution-jmap-rules 1
require ["imap4flags"];

# rule {"name":"Mark","enabled":true,"conditions":[],"combine":"All","actions":["MarkRead","Flag"],"stop":false}
if true {
    addflag "\\Seen";
    addflag "\\Flagged";
}
"#;
    let blob_mark = upload_blob(&server, mark_script.as_bytes());
    let res_mark = validate_blob(&server, &blob_mark);
    assert!(
        res_mark["methodResponses"][0][1]["error"].is_null(),
        "mark script must be valid: {:?}",
        res_mark
    );

    // 4. Copy rule with CopyTo (:copy and :mailboxid)
    let copy_script = r#"# Generated by Evolution (JMAP). Edit it in Evolution's account editor.
# evolution-jmap-rules 1
require ["copy", "fileinto", "mailboxid"];

# rule {"name":"Backup","enabled":true,"conditions":[{"field":"From","op":"Contains","value":"boss@example.com"}],"combine":"All","actions":[{"CopyTo":{"id":"M2","name":"Archive"}}],"stop":false}
if address :all :contains "from" "boss@example.com" {
    fileinto :copy :mailboxid "M2" "Archive";
}
"#;
    let blob_copy = upload_blob(&server, copy_script.as_bytes());
    let res_copy = validate_blob(&server, &blob_copy);
    assert!(
        res_copy["methodResponses"][0][1]["error"].is_null(),
        "copy script must be valid: {:?}",
        res_copy
    );

    // 5. Redirect and Discard rules
    let redirect_script = r#"# Generated by Evolution (JMAP). Edit it in Evolution's account editor.
# evolution-jmap-rules 1
require ["copy"];

# rule {"name":"Fwd","enabled":true,"conditions":[{"field":"To","op":"Is","value":"me@example.com"}],"combine":"All","actions":[{"Redirect":{"address":"other@example.com","keep":true}}],"stop":false}
if address :all :is "to" "me@example.com" {
    redirect :copy "other@example.com";
}

# rule {"name":"Spam","enabled":true,"conditions":[{"field":"Header":"X-Spam-Flag","op":"Is","value":"YES"}],"combine":"All","actions":["Discard"],"stop":true}
if header :is "X-Spam-Flag" "YES" {
    discard;
    stop;
}
"#;
    let blob_redirect = upload_blob(&server, redirect_script.as_bytes());
    let res_redirect = validate_blob(&server, &blob_redirect);
    assert!(
        res_redirect["methodResponses"][0][1]["error"].is_null(),
        "redirect/discard script must be valid: {:?}",
        res_redirect
    );

    // 6. Size condition (:over and :under) with allof / anyof
    let size_script = r#"# Generated by Evolution (JMAP). Edit it in Evolution's account editor.
# evolution-jmap-rules 1
require ["fileinto", "mailboxid"];

# rule {"name":"Big","enabled":true,"conditions":[{"field":"Size","op":"Over","value":"500"},{"field":"Size","op":"Under","value":"5000"}],"combine":"All","actions":[{"MoveTo":{"id":"M3","name":"Large"}}],"stop":false}
if allof(size :over 500K, size :under 5000K) {
    fileinto :mailboxid "M3" "Large";
}

# rule {"name":"AnyCondition","enabled":true,"conditions":[{"field":"Subject","op":"Contains","value":"urgent"},{"field":"From","op":"Contains","value":"vip"}],"combine":"Any","actions":[{"MoveTo":{"id":"M1","name":"Invoices"}}],"stop":false}
if anyof(header :contains "subject" "urgent", address :all :contains "from" "vip") {
    fileinto :mailboxid "M1" "Invoices";
}
"#;
    let blob_size = upload_blob(&server, size_script.as_bytes());
    let res_size = validate_blob(&server, &blob_size);
    assert!(
        res_size["methodResponses"][0][1]["error"].is_null(),
        "size condition script must be valid: {:?}",
        res_size
    );

    // 7. Test SieveScript/set create with generator script.
    let set_res = set_create(&server, "generator_managed", &blob_invoices);
    assert!(
        set_res["methodResponses"][0][1]["created"]["c1"].is_object(),
        "set create must succeed with generator script: {:?}",
        set_res
    );
}
